/**
 * The map's typefaces, embedded in the page so it works offline and as a single exported file.
 * IBM Plex Sans (400, 600) and IBM Plex Mono (400, 600), SIL Open Font License 1.1 (licenses/IBM-Plex.LICENSE),
 * subset to Latin, Latin-1 and the punctuation and arrows the map uses, as woff2.
 * Made with: pyftsubset <font>.ttf --unicodes=U+0020-007E,U+00A0-00FF,U+2010-2027,U+2190-2193,U+2212,U+2260,U+2264,U+2265,U+25B6,U+25BC --flavor=woff2
 */
export const FONT_FACES: string = [
  `@font-face { font-family:"IBM Plex Sans"; font-weight:400; font-style:normal; font-display:swap; src:url(data:font/woff2;base64,) format("woff2"); }`,
  `@font-face { font-family:"IBM Plex Sans"; font-weight:600; font-style:normal; font-display:swap; src:url(data:font/woff2;base64,) format("woff2"); }`,
  `@font-face { font-family:"IBM Plex Mono"; font-weight:400; font-style:normal; font-display:swap; src:url(data:font/woff2;base64,) format("woff2"); }`,
  `@font-face { font-family:"IBM Plex Mono"; font-weight:600; font-style:normal; font-display:swap; src:url(data:font/woff2;base64,) format("woff2"); }`,
].join("\n");
